"""Read-only MCP access to audio files already generated by ru_tube.

The MCP server does NOT call Gemini or generate new audio. Ru_tube itself
generates the files using its existing GEMINI_API_KEY configuration.
Only files from the local temp_audio directory can be listed or fetched.
The MCP connection is not automatically installed in ChatGPT.
"""
import base64
from datetime import datetime, timezone
from pathlib import Path

from mcp.server.mcpserver import MCPServer

SERVER = MCPServer(
    "RuTube Generated Audio Library",
    instructions="Only read already-generated audio using list_generated_audio and get_generated_audio. Never generate audio in this MCP.",
)
AUDIO_DIR = Path(__file__).resolve().parent / "temp_audio"
ALLOWED_EXTENSIONS = {".wav", ".mp3", ".m4a"}
MAX_AUDIO_BYTES = 7 * 1024 * 1024


@SERVER.tool()
def list_generated_audio(limit: int = 25) -> dict:
    """List ru_tube's existing generated audio files, newest first.

    This is read-only and never invokes or charges the Gemini TTS API.
    The local ru_tube program must be running on the user's own computer
    when generating audio files.
    """
    if not 1 <= limit <= 50:
        raise ValueError("limit must be 1 to 50.")
    if not AUDIO_DIR.exists():
        return {"audio_files": [], "note": "temp_audio directory does not exist yet."}
    files = [
        p for p in AUDIO_DIR.iterdir()
        if p.is_file() and p.suffix.lower() in ALLOWED_EXTENSIONS
    ]
    files.sort(key=lambda p: p.stat().st_mtime, reverse=True)
    return {
        "audio_files": [
            {
                "filename": p.name,
                "format": p.suffix.lower().removeprefix("."),
                "bytes": p.stat().st_size,
                "created_or_modified_utc": datetime.fromtimestamp(
                    p.stat().st_mtime, timezone.utc
                ).isoformat(),
            }
            for p in files[:limit]
        ],
        "directory": "temp_audio (on the user's local PC)",
        "note": "Audio created before the retention fix may already have been deleted.",
    }


@SERVER.tool()
def get_generated_audio(filename: str) -> dict:
    """Retrieve the exact bytes of a previously-generated ru_tube audio file.

    Return its base64-encoded content, suitable for import into a video editor.
    No TTS generation or billing occurs. The file must be in temp_audio;
    arbitrary filesystem paths are never accepted.
    """
    if not filename or Path(filename).name != filename or filename in {".", ".."}:
        raise ValueError("Only a filename from list_generated_audio is allowed.")
    if Path(filename).suffix.lower() not in ALLOWED_EXTENSIONS:
        raise ValueError("Only .wav, .mp3 or .m4a audio files are supported.")
    path = AUDIO_DIR / filename
    if path.is_symlink() or not path.is_file():
        raise FileNotFoundError("This generated audio file was not found.")
    size = path.stat().st_size
    if size > MAX_AUDIO_BYTES:
        raise ValueError("File is over 7MB; use a private file transfer instead.")
    mime_types = {".wav": "audio/wav", ".mp3": "audio/mpeg", ".m4a": "audio/mp4"}
    return {
        "filename": path.name,
        "mime_type": mime_types[path.suffix.lower()],
        "bytes": size,
        "audio_base64": base64.b64encode(path.read_bytes()).decode("ascii"),
        "source": "existing audio file; not newly synthesized",
    }


if __name__ == "__main__":
    SERVER.run(transport="stdio")
